from pathlib import Path
import hashlib, json, re, subprocess

REPO = Path('D:/geometry-axiom-work/geo261')
OUT = REPO / 'geometry-core/domain-decoupling'
SOURCE = REPO / '公理層.md'
text = SOURCE.read_bytes().replace(b'\r\n', b'\n').decode('utf-8')
BASE_REVISION = '1c80751150d0767ba52509537caf8d5542769ccb'
BASE_SOURCE_SHA256 = 'ab31dc36d5416762ac44932940a94f6142b72e831ceb62c0bc67375512109004'
assert hashlib.sha256(text.encode('utf-8')).hexdigest() == BASE_SOURCE_SHA256, 'SSOT changed; do not silently repin proposal'
matches = list(re.finditer(r'^(?:\*\*(D\d+[a-z]?)|([IR]\d+[a-z]?))\s', text, re.M))
assert len(matches) == 204
sections = list(re.finditer(r'^## ', text, re.M))
clauses = []
for i, match in enumerate(matches):
    end = min([m.start() for m in matches[i+1:i+2]] + [s.start() for s in sections if s.start()>match.start()] + [len(text)])
    before = text[match.start():end].rstrip('\n')
    clauses.append({'id': match.group(1) or match.group(2), 'before': before, 'start': match.start(), 'end': end})
research = Path('D:/geometry-axiom-work/geo261-research/comment-03.md').read_text(encoding='utf-8')
old_scopes = dict(re.findall(r'^\|((?:D|I|R)\d+[a-z]?) · ([GMTC]) ·', research, re.M))
assert len(old_scopes) == 204
scopes = {k: {'G':'K','M':'M','T':'W','C':'H'}[v] for k,v in old_scopes.items()}
CORE = {}
TARGET = {}
REASONS = {}
REPLACE = {}

def mixed(ids, core, target='W', reason=None):
    for id in ids.split():
        assert id in scopes
        scopes[id] = 'M'
        CORE[id] = core
        TARGET[id] = target
        REASONS[id] = reason or ('拆開共用的精確幾何／來源／交易機制與既有領域適用條件；現行完整契約由固定模板承接。' if target=='W' else '拆開共用機制與宿主的型別登記、保存或互動契約；維持原通路與交易行為。')

def replace(id, pairs, reason):
    scopes[id] = 'K'
    REPLACE[id] = pairs
    REASONS[id] = reason

