assert len(re.findall(r'^- ', exclusions_before, re.M)) == len(exclusion_scopes) == 19
exclusions_intro = '''本節的「本層」沿用其各項所述的產品能力／擴展層範圍；依分層契約，以下 19 項全部保持原限制，不表示核心抽離後可繞過它們。下表只指定原項次的責任層，不修改其接受／拒絕、首版能力或待定案狀態。K 的幾何可求值不等於 W／H 已授權建立或交換該物件。

| 原項次 | 作用域 | 分層界線 |
|---|---|---|
''' + '\n'.join('| '+str(index)+' | '+scope+' | '+reason+' |' for index,(scope,reason) in enumerate(exclusion_scopes,1))
exclusions_after = exclusions_before.replace('## 四、明確不在本層\n\n', '## 四、明確不在本層\n\n'+exclusions_intro+'\n\n', 1)
section_entries = [
    {'id':'preamble','before':preamble_before,'after':preamble_after,'reason':'新增可驗證的核心／固定木工模板／宿主分層契約及204條作用域；維持單一SSOT與全部現行公開行為，明定固定注入、完整來源圖與候選交易、所有通路不可繞過、舊文權威核心稱呼及不新增功能／格式。','changed':True},
    {'id':'exclusions','before':exclusions_before,'after':exclusions_after,'reason':'逐項指定19項既有限制由核心機制、固定模板或宿主承接；完整保留原文，不因通用化擴大已採納或未定案能力。','changed':True},
]

def build():
    # This script only emits proposal artifacts. It never writes the SSOT or reader.
    revision = BASE_REVISION
    data = {'schema':'geo261-clause-proposal/1','status':'proposed-not-approved','baseRevision':revision,
            'sourceSha256':hashlib.sha256(text.encode('utf-8')).hexdigest(),
            'clauses': [{key:c[key] for key in ('id','scope','before','after','reason','changed')} for c in clauses],
            'sections': section_entries}
    changed = [c for c in clauses if c['changed']]
    counts = ', '.join(scope+' '+str(len(ids)) for scope,ids in scope_groups.items())
    md = '# GEO-261 公理層逐條分層提案\n\n'
    md += '**狀態：提案，尚未批准；本檔與 clause-map.json 不是 SSOT，也不是閱讀器。真正的 `公理層.md`、白話與正典閱讀器未因本提案改動。**\n\n'
    md += '基準 commit：`'+revision+'`。SSOT 的 LF 正規化 SHA-256：`'+data['sourceSha256']+'`。\n\n'
    md += '本提案完整涵蓋現行 204 條（D 69、I 76、R 59），其中 '+str(len(changed))+' 條有逐字差異、'+str(len(clauses)-len(changed))+' 條保留原文；另修改前言與 §四 的作用域說明。作用域總數：'+counts+'。\n\n'
    md += 'K 是可獨立使用的精確幾何、來源圖、求值及候選交易核心；W 是預設固定注入的 woodworking/1；H 是專案與相容宿主；M 在同條內實際拆開 K 與 W／H。M 的後半保留原條文全文內容，只將既有條號／標題放在該條最前方，避免重複條號；其中現行「核心」依新前言解釋為 K 加固定策略組成的權威驗證通路。\n\n'
    md += '「不變」只表示該條文字未改，仍受前言明列的責任層與全部原驗收約束；沒有任何條文被刪除、降級或以「通用」解除原限制。完整逐條 before／after 亦保存在 clause-map.json，供獨立測試比對。批准應涵蓋本檔完整差異；批准前不據此實作未定案行為。\n\n'
    md += '| 條號 | 作用域 | 狀態 |\n|---|---|---|\n'
    md += '\n'.join('| '+c['id']+' | '+c['scope']+' | '+('修改' if c['changed'] else '不變')+' |' for c in clauses)
    md += '\n\n## 完整差異\n\n'
    for entry in [section_entries[0], *changed, section_entries[1]]:
        assert '```' not in entry['before'] and '```' not in entry['after'], entry['id']
        md += '### '+entry['id']+'\n\n#### 修改前\n\n```text\n'+entry['before']+'\n```\n\n#### 修改後\n\n```text\n'+entry['after']+'\n```\n\n#### 理由\n\n'+entry['reason']+'\n\n'
    OUT.mkdir(parents=True, exist_ok=True)
    (OUT / 'clause-map.json').write_text(json.dumps(data, ensure_ascii=False, indent=2)+'\n', encoding='utf-8', newline='\n')
    (OUT / 'AXIOM-PROPOSAL.md').write_text(md, encoding='utf-8', newline='\n')
    print(json.dumps({'clauses':len(clauses),'changed':len(changed),'scopes':{k:len(v) for k,v in scope_groups.items()},'sourceSha256':data['sourceSha256'],'output':str(OUT)},ensure_ascii=False))

if __name__ == '__main__':
    build()


